/// The string table for screens 01–09, English and Bangla.
///
/// Structured as an abstract base with one subclass per language, so a missing
/// string is a compile error rather than a blank label discovered in QA.
///
/// SAFETY STRINGS. Four strings in here are safety-critical and must never be
/// paraphrased, shortened, or regenerated by a translation tool:
/// [disclaimerBody], [riskFooter], [under18Body], [labNoDiagnosisNote].
/// The English is verbatim from `ui_spec.md` §7. The Bangla is verbatim from
/// the design prototype and is marked `@clinicianReviewPending` — it has NOT
/// yet been reviewed by a native-speaking clinician, which `ui_spec.md` §7
/// requires before launch. See [clinicianReviewPending].
///
/// Everything else may be edited freely as copy, subject to the eleven rules:
/// no "diagnosis", no "scan your health", no bare risk number.
library;

/// The Bangla safety strings still need a native-speaking clinician's sign-off
/// (`ui_spec.md` §7). Flipped to `false` only when that review has happened.
const clinicianReviewPending = true;

const supportedLanguages = <String, String>{
  'en': 'English',
  'bn': 'বাংলা',
};

